INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12801, 'Job 37:20', 'Job', 37, 20, '&nbsp;خُدائ پاک دې خبر شى څۀ چې زۀ خبرې کول غواړم، زۀ داسې ولې وکړم چې د دې په وجه مې تباه کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12802, 'Job 37:21', 'Job', 37, 21, '&nbsp;په هغه وخت کښې رڼا ته هيڅ څوک نۀ شى کتلے کله چې دا په آسمان کښې تکه سپينه وى، په کوم وخت کښې چې هوا وريځ بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12803, 'Job 37:22', 'Job', 37, 22, '&nbsp;د شمال په طرف د سرو زرو جلوه ښکارى، د خُدائ پاک نه ګېرچاپېره لوئى، شان او شوکت تاو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12804, 'Job 37:23', 'Job', 37, 23, '&nbsp;مونږ د قادر مطلق خُدائ د طاقت تصور نۀ شُو کولے، خو هغه بيا هم د اِنصاف والا او صادق دے، هغه مونږ نۀ تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12805, 'Job 37:24', 'Job', 37, 24, '&nbsp;نو په دې وجه بنى آدم د هغۀ نه يريږى، او څوک چې ځان هوښيار ګڼى نو هغه يې پرواه نۀ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12806, 'Job 38:1', 'Job', 38, 1, '&nbsp;نو مالِک خُدائ د طوفان نه ايُوب له جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12807, 'Job 38:2', 'Job', 38, 2, '&nbsp;”هغه څوک دے چې بغېر د څۀ پوهې نه زما د عقل په حقله تپوسونه کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12808, 'Job 38:3', 'Job', 38, 3, '&nbsp;نو اوس ټينګ شه، او زما د سوال جواب راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12809, 'Job 38:4', 'Job', 38, 4, '&nbsp;کله چې ما د زمکې بنياد کېښودو نو تۀ چرته وې؟ کۀ تا ته دومره پته وى نو ما ته ووايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12810, 'Job 38:5', 'Job', 38, 5, '&nbsp;چې دا به څومره غټ وى د دې پته چا لګولى ده؟ او په دې چا د ناپ کرښه راښکلې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12811, 'Job 38:6', 'Job', 38, 6, '&nbsp;د دې بنيادونه په څۀ باندې ودرېدل، او د دې د ګوټ کاڼے چا کېښودو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12812, 'Job 38:7', 'Job', 38, 7, '&nbsp;چې کله د سحر ستورو په يو ځائ سندرې وئيلې او ټولو فرښتو د خوشحالۍ نه چغې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12813, 'Job 38:8', 'Job', 38, 8, '&nbsp;کله چې سمندر زمکې ته راخلاص شو، نو دا چا قابو کړو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12814, 'Job 38:9', 'Job', 38, 9, '&nbsp;کله چې ما وريځ د دې لِباس جوړ کړو، او دا ما په تکه توره تيارۀ کښې راونغښتلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12815, 'Job 38:10', 'Job', 38, 10, '&nbsp;او د دې دپاره مې حدونه جوړ کړل، او را ايسار مې کړو چې د حد نه وانۀ وړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12816, 'Job 38:11', 'Job', 38, 11, '&nbsp;او ورته مې ووئيل چې د دې نه وړاندې به نۀ راځې، او ستا زورَورې چپې دې دلته ايسارې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12817, 'Job 38:12', 'Job', 38, 12, '&nbsp;تا کله حُکم کړے دے چې سحر دې شى، او نمر ته دې وئيلى دى چې د نمرخاتۀ طرف نه راوخېژى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12818, 'Job 38:13', 'Job', 38, 13, '&nbsp;تا سحر له حُکم ورکړے دے چې په زمکه خور شى، او چې د شپې بدعملى ختمه کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12819, 'Job 38:14', 'Job', 38, 14, '&nbsp;او بيا زمکه د رڼا د وجې صفا ښکارى، او رنګ يې د رنګدارو جامو په شان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12820, 'Job 38:15', 'Job', 38, 15, '&nbsp;رڼا د بدعمله خلقو کارونه بندوى، او هغوئ نور ظلم زياتے نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12821, 'Job 38:16', 'Job', 38, 16, '&nbsp;تا هغه چينې ليدلې دى چې سمندر ترې نه جوړيږى، يا تا د دې ډوبوالے معلوم کړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12822, 'Job 38:17', 'Job', 38, 17, '&nbsp;د مرګ دروازه تا ته ښکاره شوې ده څۀ؟ يا تا د تکې تورې تيارې دروازې ليدلې دى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12823, 'Job 38:18', 'Job', 38, 18, '&nbsp;تۀ د دُنيا په لوئ والى پوهه شوے يې څۀ؟ کۀ د دې نه خبر يې نو ما ته ووايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12824, 'Job 38:19', 'Job', 38, 19, '&nbsp;رڼا د کوم ځائ نه راځى، او د تيارې ځائ چرته دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12825, 'Job 38:20', 'Job', 38, 20, '&nbsp;تۀ دا هر يو خپل خپل کور ته بوتلے شې څۀ؟ تا ته پته شته چې هغې ته کومه لار تلې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12826, 'Job 38:21', 'Job', 38, 21, '&nbsp;خو تۀ خو به د دې هر څۀ نه خبر يې کنه؟ ځکه چې د دې پېدا کېدو نه وړاندې تۀ موجود وې، او تۀ د ډېرې مودې يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12827, 'Job 38:22', 'Job', 38, 22, '&nbsp;تۀ د واورې ګودامونو ته ننوتلے يې څۀ، يا تا د ږلۍ ګودامونه ليدلى دى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12828, 'Job 38:23', 'Job', 38, 23, '&nbsp;هغه چې ما د مصيبت د وخت دپاره ساتلى دى، او د جنګ جګړې دپاره مې ساتلى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12829, 'Job 38:24', 'Job', 38, 24, '&nbsp;هغه ځائ ته تلے يې څۀ چرته چې نمر راخېژى، او د کوم ځائ نه چې د نمرخاتۀ هوا لګى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12830, 'Job 38:25', 'Job', 38, 25, '&nbsp;د دروند باران لارې چا جوړې کړې دى، او د تندر د برېښنا دپاره يې لار صفا کړې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12831, 'Job 38:26', 'Job', 38, 26, '&nbsp;په هغه مُلک باندې څوک باران راولى چرته چې هيڅ څوک نۀ اوسيږى، په هغه صحرا باندې، چې هغه د بنيادمو نه خالى وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12832, 'Job 38:27', 'Job', 38, 27, '&nbsp;چې هغه تږې او اوچه زمکه اوبۀ کړى، او چې په هغه زمکه باندې واښۀ راشنۀ کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12833, 'Job 38:28', 'Job', 38, 28, '&nbsp;ولې د باران پلار شته څۀ، يا پرخه چا پېدا کړې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12834, 'Job 38:29', 'Job', 38, 29, '&nbsp;د واورې مور څوک ده؟ او د آسمان يخ له ژوند څوک ورکوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12835, 'Job 38:30', 'Job', 38, 30, '&nbsp;کومه چې اوبۀ د کاڼى په شان سختې کړى، او د سمندر مخ کلک کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12836, 'Job 38:31', 'Job', 38, 31, '&nbsp;تۀ عقدِ ثُريا ستورو ته لار ښودلے شې، يا جبار ستورے په مينځ بېلولے شې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12837, 'Job 38:32', 'Job', 38, 32, '&nbsp;ولې تۀ منطقتُ البُروج ستورو ته خپل موسمونه ښودلے شې، يا تۀ بناتُ النعش ستورى ته سره د هغې د بچو لار ښودلے شې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12838, 'Job 38:33', 'Job', 38, 33, '&nbsp;تۀ د آسمان په قانون پوهېږې څۀ؟ يا تۀ د هغوئ قانون په زمکه باندې قائمولے شې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12839, 'Job 38:34', 'Job', 38, 34, '&nbsp;ولې تۀ خپل آواز وريځو ته رسولے شې څۀ، د دې دپاره چې باران ووروى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12840, 'Job 38:35', 'Job', 38, 35, '&nbsp;تۀ برېښنا ځلولے شې څۀ؟ يا دا پخپله مرضۍ باندې راغورزولے شې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12841, 'Job 38:36', 'Job', 38, 36, '&nbsp;خبره په زړۀ کښې چا اچولې ده، او دماغو له پوهه چا ورکړې ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12842, 'Job 38:37', 'Job', 38, 37, '&nbsp;داسې هوښيار شته چې وريځې وشمېرى؟ يا د آسمان نه باران ورولے شى داسې لکه چې د منګى نه اوبۀ توئ کړے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12843, 'Job 38:38', 'Job', 38, 38, '&nbsp;په هغه اوچه زمکه باندې چې د خاورې نه يې لوټې جوړې شوې وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12844, 'Job 38:39', 'Job', 38, 39, '&nbsp;ولې تۀ د ازمرى دپاره ښکار کولے شې، او د وړو زمرو لوږه پوره کولے شې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12845, 'Job 38:40', 'Job', 38, 40, '&nbsp;کله چې هغه په خپلو غارونو کښې پټ وى، يا په بوټو کښې د ښکار په اِنتظار ناست وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12846, 'Job 38:41', 'Job', 38, 41, '&nbsp;کارغانو دپاره د خوراک بندوبست څوک کوى، کله چې د هغوئ بچى خُدائ پاک ته ژړا کوى، او د خوراک د نشتوالى په وجه سرګردانه ګرځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12847, 'Job 39:1', 'Job', 39, 1, '&nbsp;تا ته پته شته چې کله د غرۀ چېلۍ بچى راوړى؟ ولې تۀ پرې نظر ساتې چې کله هوسۍ بچى راوړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12848, 'Job 39:2', 'Job', 39, 2, '&nbsp;ولې تا ته پته شته چې دا بچى څو مياشتې د هغوئ په ګېډه وى؟ او تا ته د هغه وخت پته شته څۀ چې دا به کله پېدا شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12849, 'Job 39:3', 'Job', 39, 3, '&nbsp;کله چې هغوئ د اولاد د پېدا کېدو دپاره کښېنى، او د هغوئ بچى پېدا شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12850, 'Job 39:4', 'Job', 39, 4, '&nbsp;د هغوئ بچى تکړه شى او په ځنګل کښې لوئيږى، هغوئ ترې نه لاړ شى او واپس ورله نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12851, 'Job 39:5', 'Job', 39, 5, '&nbsp;ځنګلى خرونه چا پرېښې دى چې خوشى لاړ شى؟ دا چا آزاد پرېښى دى چې ګرځى راګرځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12852, 'Job 39:6', 'Job', 39, 6, '&nbsp;ما دا په صحرا کښې پرېښى دى، او د مالګې مُلک مې ورکړے دے چې په کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12853, 'Job 39:7', 'Job', 39, 7, '&nbsp;هغه د ښار د شور نه نفرت کوى، او خرکار ورسره نشته چې په دې باندې آواز وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12854, 'Job 39:8', 'Job', 39, 8, '&nbsp;دا غرونو ته ځى چې دا يې د څرن زمکه شى، او هر يو شين بوټے د خوراک دپاره لټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12855, 'Job 39:9', 'Job', 39, 9, '&nbsp;ولې ځنګلى غوَيے به تا پرېږدى چې کار ترېنه واخلى؟ هغه به ستا په اخور کښې شپه تېره کړى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12856, 'Job 39:10', 'Job', 39, 10, '&nbsp;ولې تۀ يو ځنګلى غوَيے د يوې دپاره تړلے شې؟ دا به ستا دپاره يو پټے يوه کړى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12857, 'Job 39:11', 'Job', 39, 11, '&nbsp;ولې تۀ د هغې لوئ طاقت باندې اعتبار کولے شې چې هغه به ستا مدد وکړى؟ تۀ په دې باندې دا يقين کولے شې څۀ چې دا به ستا دپاره کار وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12858, 'Job 39:12', 'Job', 39, 12, '&nbsp;تۀ په دې يقين کوې چې دا به واپس راشى، او ستا درمند ته به ګېډى راوړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12859, 'Job 39:13', 'Job', 39, 13, '&nbsp;د شتر‌مرغ وزر ښائسته کولاو خوريږى، خو دا د زاڼې د وزرو برابر کېدے خو نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12860, 'Job 39:14', 'Job', 39, 14, '&nbsp;شتر‌مرغ خپلې هګۍ د دې دپاره په زمکه پرېږدى، چې ګرمى شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12861, 'Job 39:15', 'Job', 39, 15, '&nbsp;دا فکر نۀ کوى چې د څۀ پښې لاندې به راشى، او چې يو ځنګلى ځناور به يې ذرې ذرې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12862, 'Job 39:16', 'Job', 39, 16, '&nbsp;دا په خپل بچى باندې داسې ظلم کوى، چې ګنې دا يې خپل نۀ وى، او کۀ مرى نو پرواه يې نۀ ساتى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12863, 'Job 39:17', 'Job', 39, 17, '&nbsp;ځکه چې خُدائ پاک د هغې نه عقل اخستے دے، او هيڅ پوهه يې نۀ ده ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12864, 'Job 39:18', 'Job', 39, 18, '&nbsp;خو کله چې پاڅى او منډه کړى، نو بيا څوک چې په آس ناست هم وى د دې نه مخکښې کېدے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12865, 'Job 39:19', 'Job', 39, 19, '&nbsp;ولې آس له طاقت تا ورکړے دے؟ د هغۀ په څټ باندې وېښتۀ تا پېدا کړى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12866, 'Job 39:20', 'Job', 39, 20, '&nbsp;د قحطۍ مُولخانو په شان د دې ټوپ تا جوړ کړے دے؟ او يا د دې هغه د رُعب والا آوازونه تا جوړ کړى دى څۀ چې خلق يروى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12867, 'Job 39:21', 'Job', 39, 21, '&nbsp;دا په پښه باندې زمکه ټکوى او په خپل طاقت په هغه وخت خوشحاليږى چې د جنګ دپاره ولېږلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12868, 'Job 39:22', 'Job', 39, 22, '&nbsp;دا يرې پورې خندا کوى او نۀ بې‌حوصلې کيږى، او د تُورې نه نۀ شاته کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12869, 'Job 39:23', 'Job', 39, 23, '&nbsp;په دې باندې سورلۍ سره د غشو تيلۍ ځلېدونکې نېزه او وړه نېزه هم آواز پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12870, 'Job 39:24', 'Job', 39, 24, '&nbsp;د جوش او د غصې د وجې دا په تېزۍ سره ځى، دا د بيګل د غږېدو پورې صبر نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12871, 'Job 39:25', 'Job', 39, 25, '&nbsp;کله چې بيګل وغږيږى نو آس يو هڼ آواز وکړى. د لرې ځائ نه هغۀ له د جنګ بوئ ورځى، د جنګى مشرانو د تندر په شان آواز او چغې اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12872, 'Job 39:26', 'Job', 39, 26, '&nbsp;ولې باښه ستا د عقل په وجه الوځى، چې خپل وزر خوارۀ کړى او د جنوب طرف ته والوځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12873, 'Job 39:27', 'Job', 39, 27, '&nbsp;باز ستا په حُکم بره خېژى او په اوچت ځائ خپله جاله جوړوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12874, 'Job 39:28', 'Job', 39, 28, '&nbsp;دا په اوچت ګټ باندې اوسيږى او خپل کور جوړوى او د ګټ په سر باندې په يو محفوظ ځائ کښې شپه تېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12875, 'Job 39:29', 'Job', 39, 29, '&nbsp;د هغه ځائ نه يې په ښکار باندې نظر وى، او د هغۀ سترګې ښکار د لرې ځائ نه وينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12876, 'Job 39:30', 'Job', 39, 30, '&nbsp;د دې بچى وينه څښى، او چې په کوم ځائ کښې مرداره وى، نو هغه په هغه ځائ کښې حاضر وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12877, 'Job 40:1', 'Job', 40, 1, '&nbsp;بيا مالِک خُدائ ايُوب ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12878, 'Job 40:2', 'Job', 40, 2, '&nbsp;”تۀ اوس هم د قادر خُدائ سره بحث کول غواړې څۀ؟ څوک چې د خُدائ پاک سره بحث کوى نو هغه به جواب ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12879, 'Job 40:3', 'Job', 40, 3, '&nbsp;بيا ايُوب مالِک خُدائ له جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12880, 'Job 40:4', 'Job', 40, 4, '&nbsp;”ګوره، زۀ هيڅ هم نۀ يم، زۀ به تا له څۀ جواب درکړم؟ زۀ په خپله خولۀ باندې لاس ږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12881, 'Job 40:5', 'Job', 40, 5, '&nbsp;ما ډېر څۀ وئيلى دى، نور زۀ څۀ نۀ وايم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12882, 'Job 40:6', 'Job', 40, 6, '&nbsp;بيا مالِک خُدائ د طوفان نه ايُوب له جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12883, 'Job 40:7', 'Job', 40, 7, '&nbsp;”نو اوس ورته ټينګ شه، زۀ به ستا نه تپوس وکړم او تۀ به ما له جواب راکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12884, 'Job 40:8', 'Job', 40, 8, '&nbsp;ولې تۀ د دې ثابِتولو کوشش کوې چې زۀ بې‌اِنصافه يم، او ما غلط وګڼې او خپل ځان ته صحيح ووائې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12885, 'Job 40:9', 'Job', 40, 9, '&nbsp;تۀ د خُدائ پاک په شان تکړه يې څۀ، ستا آواز د هغۀ د تندر د آواز په شان کېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12886, 'Job 40:10', 'Job', 40, 10, '&nbsp;کۀ داسې وى نو په رُعب داب او شان و شوکت سره خپل ځان سنګار کړه، د عزت او درناوى په جامو باندې خپل ځان پټ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12887, 'Job 40:11', 'Job', 40, 11, '&nbsp;خپل ځان په قهر کړه، هر يو مغرور سړى ته ګوره او هغه سپک کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12888, 'Job 40:12', 'Job', 40, 12, '&nbsp;ټولو مغروره خلقو ته وګوره او هغوئ عاجزان کړه، او بدعمله خلق ټک سره ووژنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12889, 'Job 40:13', 'Job', 40, 13, '&nbsp;هغوئ ټول په خاورو کښې ښخ کړه، او هغوئ قبر کښې قېد کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12890, 'Job 40:14', 'Job', 40, 14, '&nbsp;نو زۀ به دې هم صِفت وکړم، ځکه چې خپل طاقت تا بچ کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12891, 'Job 40:15', 'Job', 40, 15, '&nbsp;دريابى مېښې ته وګوره، چې هغه مې هم هغه شان جوړه کړې ده لکه څنګه مې چې تۀ جوړ کړے يې، دا د يو غوَيى په شان واښۀ خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12892, 'Job 40:16', 'Job', 40, 16, '&nbsp;د هغې طاقت د هغې په بدن کښې دے، او د هغې طاقت د هغې د خېټې په پټو کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12893, 'Job 40:17', 'Job', 40, 17, '&nbsp;د هغې لکۍ لکه د دِيار د ونې په شان سخته ده، د هغې د پتُون پټې خپلو کښې غوټه شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12894, 'Job 40:18', 'Job', 40, 18, '&nbsp;د دې هډوکى د زېړو نلکې دى، د هغې هډوکى د اوسپنې سيخونه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12895, 'Job 40:19', 'Job', 40, 19, '&nbsp;دا د خُدائ پاک د کارنامو يو لوئ کار دے، او صرف د دې خالِق په دې باندې قابو موندلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12896, 'Job 40:20', 'Job', 40, 20, '&nbsp;ځکه چې غرونه د دې دپاره خوراک پېدا کوى چرته چې ټول ځنګلى ځناور لوبې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12897, 'Job 40:21', 'Job', 40, 21, '&nbsp;دا په اوبو کښې د نيلوفر بوټو لاندې پراتۀ وى او د لوخې په ډنډونو کښې پټ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12898, 'Job 40:22', 'Job', 40, 22, '&nbsp;د نيلوفر بوټى ورباندې سورے کوى، او د نِهر د غاړې د وَلو ونې د دې نه ګېرچاپېره تاو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12899, 'Job 40:23', 'Job', 40, 23, '&nbsp;کۀ سيند په موج کښې وى، نو دا نۀ يريږى، د اُردن سيند کۀ تر خولې پورې هم ډک وى نو دا نۀ يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12900, 'Job 40:24', 'Job', 40, 24, '&nbsp;څوک دا د کُنډو سره راوچتولے شى، يا يې څوک په پوزه کښې د قابو کولو دپاره پېزوان اچولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');